@pytest.mark.parametrize("digits", [1, 8, 9, 10, 18, 19, 4301, 5000])
def test_integer_helpers_signed_zero_padded_and_bounded(monkeypatch, digits):
    # Guard module-local builtins, not process-wide conversion settings. The
    # nine-digit bound is stricter than Python 3.11's default 4300-digit limit.
    def bounded_int(text):
        if len(text) > 9:
            raise ValueError("unbounded decimal parsing")
        return int(text)

    def bounded_str(value):
        if not 0 <= value < 1_000_000_000:
            raise ValueError("unbounded decimal rendering")
        return str(value)

    get_limit = getattr(sys, "get_int_max_str_digits", lambda: None)
    limit = get_limit()
    monkeypatch.setattr(model, "int", bounded_int, raising=False)
    monkeypatch.setattr(model, "str", bounded_str, raising=False)
    raw = "9" * digits
    expected = 10 ** digits - 1
    for sign in ("", "+", "-"):
        value = -expected if sign == "-" else expected
        assert model.parse_integer(sign + "000" + raw) == value
        assert model.integer_text(value) == ("-" if sign == "-" else "") + raw
        assert model.parse_integer(sign + "0" * digits) == 0
    assert model.integer_text(0) == "0"
    assert get_limit() == limit

    assert eof.kind == "EOF"


@pytest.mark.parametrize("raw,expected", [
    ("9" * 4301, 10 ** 4301 - 1),
    ("0" * 4301 + "7", 7),
    ("0" * 4301, 0),
], ids=["large", "leading-zeros", "zero"])
def test_integer_over_default_digit_limit(monkeypatch, raw, expected):
    def limited_int(text):
        if len(text) > 4300:
            raise ValueError("decimal conversion exceeds 4300 digits")
        return int(text)

    # Cover both the old lexer conversion and the shared helper on hosts that
    # lack Python 3.11's limit API, without changing process-global settings.
    monkeypatch.setattr(lexer, "int", limited_int, raising=False)
    monkeypatch.setattr(model, "int", limited_int, raising=False)
    with pytest.raises(ValueError):
        limited_int(raw)
    token, eof = tokenize("\n\t" + raw)
    assert token.kind == "INT" and type(token.value) is int
    assert token.value == expected
    assert (token.raw, token.start, token.end, token.line, token.column) == (
        raw, 2, len(raw) + 2, 2, 2,
    )
    assert (eof.start, eof.end, eof.line, eof.column) == (
        len(raw) + 2, len(raw) + 2, 2, len(raw) + 2,
    )


